const D = { energy:.62, scale:1, density:.55, speed:1, gamma:2.2, persist:.5, hue:200, x:.5, y:.5, style:'plasma', seed:0, alpha:100, act:'breathe' };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- coarse density grid (long axis 240; keyed on aspect, survives resize) ----
const LA = 240;
let cw, ch;
if (width >= height){ cw = LA; ch = Math.max(64, Math.round(LA*height/width)); }
else { ch = LA; cw = Math.max(64, Math.round(LA*width/height)); }
if (S.gridKey !== cw+'x'+ch){
  S.gridKey = cw+'x'+ch; S.cw = cw; S.ch = ch;
  S.hist = new Float32Array(cw*ch);
  S.csum = new Float32Array(cw*ch);
  if (S.buf) S.buf.remove();
  S.buf = createGraphics(cw, ch); S.buf.pixelDensity(1);
}
cw = S.cw; ch = S.ch; const NG = cw*ch;

// ---- seeded De Jong basin (rebuild only on seed change) ----
if (S.seedUsed !== P.seed){
  S.seedUsed = P.seed;
  const fr = i => { const q = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return q - Math.floor(q); };
  const BAS = [ [1.4,-2.3,2.4,-2.1], [-2.0,-2.0,-1.2,2.0], [2.01,-2.53,1.61,-0.33], [-2.7,-0.09,-0.86,-2.2], [-0.827,-1.637,1.659,-0.943], [1.641,1.902,0.316,1.525], [-2.24,0.43,-0.65,-2.43], [1.5,-1.8,1.6,2.0] ];
  const base = BAS[Math.floor(fr(9)*BAS.length) % BAS.length];
  S.ba = base[0] + (fr(1)*2-1)*0.35;
  S.bb = base[1] + (fr(2)*2-1)*0.35;
  S.bc = base[2] + (fr(3)*2-1)*0.35;
  S.bd = base[3] + (fr(4)*2-1)*0.35;
  S.hoff = fr(5); S.rot0 = fr(6)*6.283; S.secOff = fr(7)*6.283;
  S.ox = 0.1; S.oy = 0.1; S.opx = 0.1; S.opy = 0.1; S.burn = 40;
  if (S.hist) S.hist.fill(0);
  if (S.csum) S.csum.fill(0);
  S.palKey = null;
}

// ---- palette LUT (256x3), built once per style/hue/seed change ----
if (S.palKey !== P.style+'|'+Math.round(P.hue)+'|'+P.seed){
  S.palKey = P.style+'|'+Math.round(P.hue)+'|'+P.seed;
  const pal = S.pal || (S.pal = new Float32Array(768));
  const h0 = P.hue/360 + S.hoff*0.12, TAU = 6.28318, st = P.style;
  for (let i=0;i<256;i++){ const t = i/255; let r,g,b;
    if (st==='thermal'){
      r = Math.min(1, t*1.95);
      g = Math.max(0, Math.min(1, (t-0.30)*1.9));
      b = Math.max(0, Math.min(1, (t-0.72)*3.6)) + Math.max(0,(0.16-t))*0.9;
    } else if (st==='ink'){ r = g = b = t; }
    else if (st==='blueprint'){ r = 0.12+t*0.5; g = 0.4+t*0.55; b = 0.62+t*0.38; }
    else if (st==='iridescent'){
      const rr = 0.5+0.5*Math.cos(TAU*(h0+t*0.85+0.00));
      const gg = 0.5+0.5*Math.cos(TAU*(h0+t*0.85+0.33));
      const bb = 0.5+0.5*Math.cos(TAU*(h0+t*0.85+0.67));
      r = 0.5+rr*0.5; g = 0.52+gg*0.48; b = 0.58+bb*0.42;
    } else {
      r = 0.5+0.5*Math.cos(TAU*(h0+t+0.00));
      g = 0.5+0.5*Math.cos(TAU*(h0+t+0.33));
      b = 0.5+0.5*Math.cos(TAU*(h0+t+0.67));
    }
    pal[i*3]=r; pal[i*3+1]=g; pal[i*3+2]=b;
  }
}
const pal = S.pal;

// ---- temporal program: continuous K.t drift floor + eased section arc ----
const intn = (K.intensity!=null?K.intensity:0.6);
const sec = (K.section!=null?K.section:0);
if (S.secSm == null || sec < S.secSm - 4) S.secSm = sec;
S.secSm += (sec - S.secSm)*0.03;
const secSm = S.secSm;
let driftAmp = 0.20, rotRate = 0.05, expScale = 1.0;
if (P.act==='surge'){ driftAmp = 0.15+intn*0.30; rotRate = 0.045+intn*0.13; expScale = 0.75+intn*0.6; }
else if (P.act==='drift'){ driftAmp = 0.10; rotRate = 0.028; expScale = 0.9; }
const T = K.t*P.speed;
const secShift = Math.sin(secSm*0.9 + S.secOff);
const a = S.ba + Math.sin(T*0.043)*driftAmp*1.3 + secShift*0.30;
const b = S.bb + Math.cos(T*0.037+1.7)*driftAmp*1.2 - secShift*0.24;
const c = S.bc + Math.sin(T*0.031+3.1)*driftAmp*1.1 + Math.cos(secSm*0.7)*0.22;
const d = S.bd + Math.cos(T*0.051+4.4)*driftAmp*1.2 - Math.sin(secSm*0.6)*0.20;
const rot = S.rot0 + K.t*rotRate*P.speed;
const cr = Math.cos(rot), sr = Math.sin(rot);

// ---- rolling decay + running max (pass 1) ----
const decay = 0.80 + P.persist*0.17;
const hist = S.hist, csum = S.csum;
let nMax = 0;
for (let i=0;i<NG;i++){ const v = hist[i]*decay; hist[i]=v; csum[i]*=decay; if (v>nMax) nMax=v; }

// ---- De Jong iteration -> density + radial/velocity structural color ----
let iters = Math.floor((2200 + P.density*5200)*(0.7+intn*0.5) + A.bass*1600);
if (iters>11000) iters=11000;
const uMin = (cw<ch?cw:ch), spanPix = uMin/4.6;
const cx = P.x*cw, cy = P.y*ch, sc = spanPix*P.scale;
let x = S.ox, y = S.oy, px = S.opx, py = S.opy, burn = S.burn|0;
for (let it=0; it<iters; it++){
  const nx = Math.sin(a*y) - Math.cos(b*x);
  const ny = Math.sin(c*x) - Math.cos(d*y);
  px = x; py = y; x = nx; y = ny;
  if (burn>0){ burn--; continue; }
  const vx = x-px, vy = y-py;
  let cc = Math.sqrt(x*x+y*y)*0.34 + Math.abs(vx-vy)*0.09; if (cc>1) cc = 1;
  const rx = x*cr - y*sr, ry = x*sr + y*cr;
  const ix = (cx + rx*sc)|0, iy = (cy + ry*sc)|0;
  if (ix>=0 && ix<cw && iy>=0 && iy<ch){ const bi = iy*cw+ix; const nv = hist[bi]+1; hist[bi]=nv; csum[bi]+=cc; if (nv>nMax) nMax=nv; }
}
S.ox = x; S.oy = y; S.opx = px; S.opy = py; S.burn = 0;

// ---- log-density + gamma tone map -> coarse buffer (pass 2) ----
const expo = (0.5 + P.energy*2.0 + intn*0.5)*expScale + K.pulse*0.20 + A.rms*1.0;
const invG = 1/Math.max(0.3, P.gamma);
const logMax = Math.log(1 + nMax*expo) + 1e-3;
const st = P.style, ink = (st==='ink');
let bgR,bgG,bgB;
if (ink){ bgR=214; bgG=207; bgB=195; }
else if (st==='blueprint'){ bgR=6; bgG=15; bgB=42; }
else if (st==='iridescent'){ bgR=14; bgG=13; bgB=20; }
else { bgR=6; bgG=4; bgB=14; }
const buf = S.buf; buf.loadPixels(); const q = buf.pixels;
for (let i=0;i<NG;i++){ const n = hist[i]; let R,G,B;
  if (n < 1e-3){ R=bgR; G=bgG; B=bgB; }
  else {
    let br = Math.log(1+n*expo)/logMax; if (br>1) br=1; br = Math.pow(br, invG);
    if (st==='thermal'){ const k=(br*255)|0; R=pal[k*3]*255; G=pal[k*3+1]*255; B=pal[k*3+2]*255; }
    else if (ink){ const val = 1 - br*0.9; R = bgR*val; G = bgG*val; B = bgB*val*0.97; }
    else if (st==='blueprint'){
      const band = Math.abs(((br*6)%1)-0.5);
      const line = band<0.11 ? (0.11-band)*9 : 0;
      R = bgR + br*36 + line*60;
      G = bgG + br*150 + line*170;
      B = bgB + br*150 + line*200;
    }
    else if (st==='iridescent'){
      let cco = csum[i]/n; const ph = (cco*1.2 + br*0.45 + n*0.015)%1; let k=(ph*255)|0; if(k<0)k+=256; k&=255;
      const sh = 0.4 + br*0.6;
      R = pal[k*3]*255*sh; G = pal[k*3+1]*255*sh; B = pal[k*3+2]*255*sh;
    }
    else { let k=((csum[i]/n)*255)|0; if(k<0)k=0; if(k>255)k=255; R = pal[k*3]*255*br; G = pal[k*3+1]*255*br; B = pal[k*3+2]*255*br; }
  }
  const p4 = i*4;
  q[p4]   = R<0?0:(R>255?255:R);
  q[p4+1] = G<0?0:(G>255?255:G);
  q[p4+2] = B<0?0:(B>255?255:B);
  q[p4+3] = 255;
}
buf.updatePixels();

// ---- upscale + additive glow bloom, alpha for VJ compositing ----
push();
if (P.alpha < 100){
  tint(0,0,100,P.alpha);
  image(buf,0,0,width,height);
  noTint();
} else {
  image(buf,0,0,width,height);
  if (ink){ /* light-key sumi: no additive bloom */ }
  else if (st==='blueprint'){ blendMode(ADD); tint(0,0,100,12+P.energy*14); image(buf,0,0,width,height); noTint(); blendMode(BLEND); }
  else { blendMode(ADD); tint(0,0,100,20+P.energy*26); image(buf,0,0,width,height); noTint(); blendMode(BLEND); }
}
